artifacts.terraform/main.tf:
terraform {
  required_version = "= 1.16.5"
  required_providers {
    proxmox = {
      source  = "telmate/proxmox"
      version = "3.0.2-rc10"
    }
  }
}
provider "proxmox" {
  pm_api_url                  = "https://10.9.9.20:8006/api2/json"
  pm_tls_insecure             = true
  pm_minimum_permission_check = false
  pm_parallel                 = 1
}
resource "proxmox_vm_qemu" "lab" {
  for_each = {
    "981" = "csi-lab-server"
    "982" = "csi-lab-worker-1"
    "983" = "csi-lab-worker-2"
  }
  vmid               = tonumber(each.key)
  name               = each.value
  pool               = "csi-lab-20261003"
  target_node        = "pve"
  clone              = "packer-debian-13.7.0-20260919201032"
  full_clone         = true
  description        = "Disposable CSI lab 20261003; synthetic data only; update test"
  tags               = "csi-lab-20261003"
  scsihw             = "virtio-scsi-pci"
  boot               = "order=virtio0"
  start_at_node_boot = false
  agent              = 1
  skip_ipv6          = true
  memory             = 2048
  cpu {
    sockets = 1
    cores   = 2
    type    = "host"
  }
  power_state = "running"
  hotplug     = "network,disk,usb"
  os_type     = "cloud-init"
  ciuser      = "csi-lab"
  ciupgrade   = false
  sshkeys     = file("/root/csi-lab/id_ed25519.pub")
  ipconfig0   = "ip=dhcp"
  network {
    id     = 0
    model  = "virtio"
    bridge = "vmbr0"
  }
  disks {
    ide {
      ide2 {
        cloudinit {
          storage = "vm-pool"
        }
      }
    }
    virtio {
      virtio0 {
        disk {
          size     = "8G"
          storage  = "vm-pool"
          iothread = true
          discard  = true
        }
      }
    }
  }
  lifecycle {
    ignore_changes = [startup_shutdown, disks[0].scsi]
  }
}
output "lab_ips" {
  value = { for k, v in proxmox_vm_qemu.lab : k => v.default_ipv4_address }
}
